import React from 'react';
import PropTypes from 'prop-types';
import TicketBooking from '../EventOwner/TicketManagement'; // Import the ticket booking component
import './EventList.css'; // Import your CSS for styling

const EventList = ({ events }) => {
  if (!events || events.length === 0) {
    return <p>No events available.</p>;
  }

  return (
    <div className="event-list">
      <h3>Your Events</h3>
      <ul>
        {events.map((event) => (
          <li key={event._id} className="event-item">
            <h4>{event.eventName}</h4>
            <p>Date: {new Date(event.eventDate).toLocaleDateString()}</p>
            <p>Location: {event.location}</p>
            <p>Description: {event.description}</p>
            <TicketBooking eventId={event._id} /> {/* Pass the event ID to the booking component */}
          </li>
        ))}
      </ul>
    </div>
  );
};

// Define the prop types for validation
EventList.propTypes = {
  events: PropTypes.arrayOf(
    PropTypes.shape({
      _id: PropTypes.string.isRequired,
      eventName: PropTypes.string.isRequired,
      eventDate: PropTypes.string.isRequired,
      location: PropTypes.string.isRequired,
      description: PropTypes.string.isRequired,
    })
  ).isRequired,
};

export default EventList;



